 * 3. 完整追溯鏈資訊
 */

interface ReceivingDetailProps {
  item: {
    lotId: number;
    poNumber: string;
    vendorName: string;

    // 三層識別碼
    internalSku: string;
    internalLotNumber: string;
    internalBarcode: string;

    // 供應商追溯
    vendorPn: string;
    vendorLotCode: string;
    vendorDateCode?: string;
    originalBarcode: string;

    // 詳細資訊
    description: string;
    quantityOnHand: number;
    unit: string;
    lotStatus: string;
    receiveDate: string;
    locationCode?: string;

    // IQC 資訊
    iqcResult?: 'PASS' | 'FAIL' | 'PENDING';
    iqcDate?: string;
    iqcInspector?: string;
    qualityNotes?: string;
  };
}

