              採購單號: {item.poNumber}
            </p>
          </div>
          <div className="text-right">
            {getIQCBadge(item.iqcResult)}
            <p className="mt-2 text-sm text-gray-500">
              收貨時間: {new Date(item.receiveDate).toLocaleString('zh-TW')}
            </p>
          </div>
        </div>
      </div>

      {/* 主要資訊 - 左右分欄 */}
      <div className="grid grid-cols-2 gap-6">

