                {item.internalLotNumber}
              </div>
              <div className="flex items-center gap-2 mt-2 text-sm text-gray-500">
                <Calendar className="w-4 h-4" />
                收貨: {new Date(item.receiveDate).toLocaleDateString('zh-TW')}
              </div>
